import { z } from "zod";
import { grantGuestPromoCredits, initializeCreditAccount } from "@/lib/billing/server";
import { applyAuthCookies, createClient, type AuthCookie } from "@/lib/supabase/server";
import { verifyTurnstile } from "@/lib/abuse/turnstile";
import { ApiRequestError, apiError, apiOk, parseJson, requestContext, retryAfter } from "@/lib/server/api";
import { logEvent, requestSubjectKey } from "@/lib/server/observability";
import { configuredLimit, consumeRateLimit } from "@/lib/server/rate-limit";

export const runtime = "nodejs";
const schema = z.object({ challengeToken: z.string().max(2048).optional(), forClean: z.boolean().default(false) });

export async function POST(request: Request) {
  const context = requestContext(request, "/api/auth/anonymous");
  const authCookies: AuthCookie[] = [];
  const subject = requestSubjectKey(request);
  const limit = consumeRateLimit("guest", subject, configuredLimit("RATE_LIMIT_GUEST_PER_MINUTE", 4), 60_000);
  if (!limit.allowed) {
    logEvent("rate_limit_triggered", { requestId: context.requestId, route: context.route, subjectHash: subject });
    return apiError(context, "rate_limited", "Too many guest-session requests. Try again shortly.", 429, retryAfter(limit.retryAfterSeconds));
  }
  try {
    const parsed = await parseJson(request, schema, 4_096);
    const challenge = await verifyTurnstile(parsed.challengeToken, "account");
    if (!challenge.ok) {
      logEvent("bot_challenge_failed", { requestId: context.requestId, route: context.route, reason: challenge.reason ?? "unknown" });
      return apiError(context, challenge.reason === "not_configured" ? "bot_protection_unavailable" : "bot_challenge_failed", challenge.reason === "not_configured" ? "Bot protection is not configured." : "Bot verification is required.", challenge.reason === "not_configured" ? 503 : 403);
    }
    const supabase = await createClient((cookiesToSet) => authCookies.push(...cookiesToSet));
    const current = await supabase.auth.getUser();
    const existing = current.data.user;
    if (existing) {
      let balance = await initializeCreditAccount(existing.id);
      let guestPromoGranted = false;
      if (parsed.forClean && existing.is_anonymous) {
        const promo = await grantGuestPromoCredits(existing.id);
        balance = promo.balance;
        guestPromoGranted = promo.granted;
      }
      logEvent("guest_session_reused", { requestId: context.requestId, userIdHash: requestSubjectKey(request, existing.id), guestPromoGranted, latencyMs: Date.now() - context.startedAt });
      return applyAuthCookies(apiOk(context, { userId: existing.id, isAnonymous: Boolean(existing.is_anonymous), balance, guestPromoGranted }), authCookies);
    }
    const { data, error } = await supabase.auth.signInAnonymously();
    if (error || !data.user) {
      logEvent("guest_session_failed", { requestId: context.requestId, status: "provider_error" });
      return apiError(context, "account_unavailable", "Could not create a guest session.", 503);
    }
    let balance = await initializeCreditAccount(data.user.id);
    let guestPromoGranted = false;
    if (parsed.forClean) {
      const promo = await grantGuestPromoCredits(data.user.id);
      balance = promo.balance;
      guestPromoGranted = promo.granted;
    }
    logEvent("guest_session_created", { requestId: context.requestId, userIdHash: requestSubjectKey(request, data.user.id), guestPromoGranted, latencyMs: Date.now() - context.startedAt });
    return applyAuthCookies(apiOk(context, { userId: data.user.id, isAnonymous: true, balance, guestPromoGranted }), authCookies);
  } catch (error) {
    if (error instanceof ApiRequestError) return apiError(context, error.code, error.message, error.status);
    logEvent("guest_session_failed", { requestId: context.requestId, status: "configuration_or_backend" });
    return apiError(context, "account_unavailable", "Account service is not available.", 503);
  }
}

let lastEdit = null;

function inputSelection() {
  const target = document.activeElement;
  if (!(target instanceof HTMLTextAreaElement || target instanceof HTMLInputElement)) return null;
  const start = target.selectionStart ?? 0;
  const end = target.selectionEnd ?? start;
  if (end <= start) return null;
  return { kind: "input", target, start, end, text: target.value.slice(start, end) };
}

function richSelection() {
  const selection = window.getSelection();
  if (!selection || selection.rangeCount === 0 || selection.isCollapsed) return null;
  const range = selection.getRangeAt(0);
  const host = range.commonAncestorContainer.nodeType === Node.ELEMENT_NODE
    ? range.commonAncestorContainer
    : range.commonAncestorContainer.parentElement;
  const editable = host?.closest?.('[contenteditable="true"]');
  return { kind: editable ? "contenteditable" : "readonly", range: range.cloneRange(), text: selection.toString(), editable };
}

function currentSelection() {
  return inputSelection() || richSelection();
}

function replaceSelection(replacement) {
  const selection = currentSelection();
  if (!selection || !selection.text) return { ok: false, reason: "Select text in an editable field first." };

  if (selection.kind === "input") {
    const { target, start, end } = selection;
    lastEdit = { kind: "input", target, start, replacementLength: replacement.length, original: selection.text };
    target.setRangeText(replacement, start, end, "end");
    target.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "insertReplacementText", data: replacement }));
    return { ok: true };
  }

  if (selection.kind === "contenteditable" && selection.editable) {
    const htmlBefore = selection.editable.innerHTML;
    const range = selection.range;
    range.deleteContents();
    range.insertNode(document.createTextNode(replacement));
    selection.editable.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "insertReplacementText", data: replacement }));
    lastEdit = { kind: "contenteditable", target: selection.editable, htmlBefore };
    return { ok: true };
  }

  return { ok: false, reason: "The selected text is read-only. Use Copy result instead." };
}

function undoLast() {
  if (!lastEdit) return { ok: false, reason: "There is no in-page edit to undo." };

  if (lastEdit.kind === "input" && document.contains(lastEdit.target)) {
    const end = lastEdit.start + lastEdit.replacementLength;
    lastEdit.target.setRangeText(lastEdit.original, lastEdit.start, end, "end");
    lastEdit.target.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "historyUndo" }));
    lastEdit = null;
    return { ok: true };
  }

  if (lastEdit.kind === "contenteditable" && document.contains(lastEdit.target)) {
    lastEdit.target.innerHTML = lastEdit.htmlBefore;
    lastEdit.target.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "historyUndo" }));
    lastEdit = null;
    return { ok: true };
  }

  lastEdit = null;
  return { ok: false, reason: "The edited element is no longer available." };
}

chrome.runtime.onMessage.addListener((message, _sender, sendResponse) => {
  if (message?.type === "selection") {
    const selection = currentSelection();
    sendResponse(selection ? { ok: true, text: selection.text, editable: selection.kind !== "readonly" } : { ok: false, reason: "Select some text first." });
    return;
  }
  if (message?.type === "replace") {
    sendResponse(replaceSelection(String(message.text || "")));
    return;
  }
  if (message?.type === "undo") {
    sendResponse(undoLast());
  }
});

import { creditCostForInput, MAX_FILE_BYTES, MAX_REWRITE_WORDS, validateFileSize, validateRewriteWordCount } from "@/lib/product-contract";
import type { BillableInputKind } from "@/lib/product-contract";

export type SanitizationIntent = "inspect" | "sanitize" | "rewrite";
export type SanitizationStage = "inspect" | "plan" | "reserve" | "sanitize" | "rewrite" | "validate" | "commit" | "receipt";

export type SanitizationJobPlan = {
  kind: BillableInputKind;
  intent: SanitizationIntent;
  stages: SanitizationStage[];
  credits: number;
  localInspection: true;
  serverAuthoritativeBilling: boolean;
  ephemeralContentProcessing: boolean;
  rewriteAllowed: boolean;
};

export class SanitizationContractError extends Error {
  constructor(public readonly code: "file_too_large" | "rewrite_too_large" | "rewrite_unsupported" | "provenance_blocked" | "missing_input", message: string) {
    super(message);
    this.name = "SanitizationContractError";
  }
}

export function planSanitizationJob(input: {
  kind: BillableInputKind;
  intent: SanitizationIntent;
  text?: string;
  bytes?: number;
  hasProvenance?: boolean;
}): SanitizationJobPlan {
  const isText = input.kind === "text" || input.kind === "txt";
  const isFile = !isText;

  if (isText && input.text === undefined) throw new SanitizationContractError("missing_input", "Text input is required.");
  if (isFile && input.bytes === undefined) throw new SanitizationContractError("missing_input", "File size is required.");
  if (isFile && !validateFileSize(input.bytes!)) throw new SanitizationContractError("file_too_large", `DOCX, PNG and JPEG jobs are limited to ${MAX_FILE_BYTES} bytes.`);
  if (input.intent === "rewrite" && !isText) throw new SanitizationContractError("rewrite_unsupported", "Semantic rewriting is available only for pasted text and TXT input.");
  if (input.intent === "rewrite" && !validateRewriteWordCount(input.text ?? "").ok) throw new SanitizationContractError("rewrite_too_large", `Semantic editing accepts at most ${MAX_REWRITE_WORDS.toLocaleString("en-US")} words per operation.`);
  if (input.intent === "sanitize" && isFile && input.hasProvenance) throw new SanitizationContractError("provenance_blocked", "Signed provenance must not be silently invalidated by sanitation.");

  if (input.intent === "inspect") {
    return { kind: input.kind, intent: input.intent, stages: ["inspect", "receipt"], credits: 0, localInspection: true, serverAuthoritativeBilling: false, ephemeralContentProcessing: false, rewriteAllowed: isText };
  }

  const credits = creditCostForInput(input.kind, input.text);
  const workStage: SanitizationStage = input.intent === "rewrite" ? "rewrite" : "sanitize";
  return {
    kind: input.kind,
    intent: input.intent,
    stages: ["inspect", "plan", "reserve", workStage, "validate", "commit", "receipt"],
    credits,
    localInspection: true,
    serverAuthoritativeBilling: true,
    ephemeralContentProcessing: true,
    rewriteAllowed: isText,
  };
}

import { normalizeManifestStore } from "./normalize";
import type { C2paVerificationReceipt } from "./types";

async function loadVerifier() {
  const { createC2pa } = await import("@contentauth/c2pa-web/inline");
  return createC2pa();
}

let verifierPromise: ReturnType<typeof loadVerifier> | null = null;

function verifier() {
  verifierPromise ??= loadVerifier();
  return verifierPromise;
}

function errorReceipt(status: C2paVerificationReceipt["status"], cause: unknown): C2paVerificationReceipt {
  const message = cause instanceof Error ? cause.message : String(cause);
  return {
    version: "c2pa-verification-v1",
    checkedAt: new Date().toISOString(),
    status,
    manifestCount: 0,
    manifestLabels: [],
    validation: [],
    verifier: "@contentauth/c2pa-web",
    note: status === "not_present"
      ? "No readable C2PA manifest was found in this asset."
      : status === "unsupported"
        ? "The official C2PA browser verifier does not support this asset in the current verification path."
        : "The official C2PA verifier could not reach a conclusive result for this asset.",
    technicalError: message,
  };
}

export async function verifyC2pa(file: File): Promise<C2paVerificationReceipt> {
  if (file.size > 20 * 1024 * 1024) {
    return errorReceipt("unsupported", new Error("Phase 2 verification is limited to 20 MB per local file."));
  }

  try {
    const c2pa = await verifier();
    const reader = await c2pa.reader.fromBlob(
      file.type || "application/octet-stream",
      file,
      { verify: { verifyTrust: true } },
    );

    if (!reader) {
      return {
        version: "c2pa-verification-v1",
        checkedAt: new Date().toISOString(),
        status: "not_present",
        manifestCount: 0,
        manifestLabels: [],
        validation: [],
        verifier: "@contentauth/c2pa-web",
        note: "The official C2PA reader found no manifest in this asset.",
      };
    }

    try {
      const store = await reader.manifestStore();
      return normalizeManifestStore(store);
    } finally {
      await reader.free();
    }
  } catch (cause) {
    const message = (cause instanceof Error ? cause.message : String(cause)).toLowerCase();
    if ((message.includes("manifest") && (message.includes("not found") || message.includes("no manifest"))) || message.includes("no c2pa")) {
      return errorReceipt("not_present", cause);
    }
    if (message.includes("unsupported") || message.includes("format")) {
      return errorReceipt("unsupported", cause);
    }
    return errorReceipt("unverifiable", cause);
  }
}

export type { C2paVerificationReceipt } from "./types";

import { NextResponse } from "next/server";
import { emailFingerprint } from "@/lib/auth/email-fingerprint";
import { claimSignupPromoCredits, initializeCreditAccount } from "@/lib/billing/server";
import { requestContext } from "@/lib/server/api";
import { hashIdentifier, logEvent } from "@/lib/server/observability";
import { applyAuthCookies, createClient, type AuthCookie } from "@/lib/supabase/server";

function safeInternalPath(value: string | null) { return value && value.startsWith("/") && !value.startsWith("//") && !value.includes("\\") ? value : "/"; }
export async function GET(request: Request) {
  const context = requestContext(request, "/auth/callback");
  const authCookies: AuthCookie[] = [];
  const url = new URL(request.url); const code = url.searchParams.get("code"); const next = safeInternalPath(url.searchParams.get("next")); const promoRequested = url.searchParams.get("promo") === "1";
  if (code) {
    try {
      const supabase = await createClient((cookiesToSet) => authCookies.push(...cookiesToSet));
      const { data, error } = await supabase.auth.exchangeCodeForSession(code);
      if (!error && data.user) {
        try { await initializeCreditAccount(data.user.id); } catch { /* auth remains valid if billing is not configured */ }
        if (promoRequested && !data.user.is_anonymous && data.user.email) {
          try {
            const promo = await claimSignupPromoCredits(data.user.id, emailFingerprint(data.user.email));
            logEvent("signup_promo_claim", { requestId: context.requestId, userIdHash: hashIdentifier(data.user.id), granted: promo.granted });
          } catch {
            logEvent("signup_promo_unavailable", { requestId: context.requestId, userIdHash: hashIdentifier(data.user.id) });
          }
        }
        logEvent("oauth_callback_success", { requestId: context.requestId, userIdHash: hashIdentifier(data.user.id) });
      }
    } catch { logEvent("oauth_callback_failed", { requestId: context.requestId, status: "configuration_or_provider" }); }
  }
  const response = NextResponse.redirect(new URL(next, url.origin)); response.headers.set("x-request-id", context.requestId); return applyAuthCookies(response, authCookies);
}

import { describe, expect, it } from "vitest";
import { MAX_FILE_BYTES } from "../src/lib/product-contract";
import { planSanitizationJob, SanitizationContractError } from "../src/lib/sanitization";

describe("unified sanitization job contract", () => {
  it("keeps inspection free and local", () => {
    const plan = planSanitizationJob({ kind: "text", intent: "inspect", text: "hello" });
    expect(plan.credits).toBe(0);
    expect(plan.stages).toEqual(["inspect", "receipt"]);
    expect(plan.serverAuthoritativeBilling).toBe(false);
  });

  it("routes text and TXT sanitation through shared word-based economics", () => {
    expect(planSanitizationJob({ kind: "text", intent: "sanitize", text: "one ".repeat(1001) }).credits).toBe(2);
    expect(planSanitizationJob({ kind: "txt", intent: "sanitize", text: "one ".repeat(1001) }).credits).toBe(2);
  });

  it("routes DOCX/PNG/JPEG sanitation as one-credit jobs", () => {
    for (const kind of ["docx", "png", "jpeg"] as const) expect(planSanitizationJob({ kind, intent: "sanitize", bytes: MAX_FILE_BYTES }).credits).toBe(1);
  });

  it("rejects oversize files and rewrites before billing", () => {
    expect(() => planSanitizationJob({ kind: "png", intent: "sanitize", bytes: MAX_FILE_BYTES + 1 })).toThrow(SanitizationContractError);
    const tooMany = Array.from({ length: 8001 }, () => "word").join(" ");
    expect(() => planSanitizationJob({ kind: "text", intent: "rewrite", text: tooMany })).toThrow(/8,000 words/i);
  });

  it("blocks destructive file sanitation when signed provenance is present", () => {
    expect(() => planSanitizationJob({ kind: "jpeg", intent: "sanitize", bytes: 100, hasProvenance: true })).toThrow(/provenance/i);
  });
});

export type SupportedFileFormat = "jpeg" | "png" | "webp" | "docx" | "pdf";

export type FileFindingKind =
  | "exif"
  | "xmp"
  | "iptc"
  | "comment"
  | "text_chunk"
  | "office_core"
  | "office_app"
  | "office_custom"
  | "pdf_info"
  | "pdf_xmp"
  | "provenance_manifest";

export type FileFindingDisposition = "privacy_metadata" | "provenance" | "review";

export interface FileFinding {
  id: string;
  kind: FileFindingKind;
  disposition: FileFindingDisposition;
  label: string;
  description: string;
  removableByDefault: boolean;
  offset?: number;
  size?: number;
}

export interface FileInspectionReceipt {
  version: "file-scan-v1";
  scannedAt: string;
  file: {
    name: string;
    format: SupportedFileFormat;
    mimeType: string;
    bytes: number;
  };
  findings: FileFinding[];
  summary: {
    total: number;
    privacyMetadata: number;
    provenance: number;
    reviewRequired: number;
    removableByDefault: number;
  };
  capabilities: {
    inspect: true;
    sanitize: boolean;
    provenanceRemoval: false;
  };
}

export interface FileSanitizeResult {
  version: "file-sanitize-v1";
  output: Uint8Array;
  outputFileName: string;
  mimeType: string;
  removed: FileFinding[];
  preserved: FileFinding[];
  before: FileInspectionReceipt;
  after: FileInspectionReceipt;
}

